for name,desc,attrs in [('Seq-MRD','B-cell receptor IgH/K/L CDR3 sequencing assay and humanB-lymphocyte MRD kit for hematological malignancy monitoring/research.',{'targets':['IgH','IgK','IgL'],'formats':['detection kit','laboratory research testing']}),('Genetron IDH1 mutation detection kit','Fluorescence-PCR kit detecting IDH1R132H in glioma tissue.',{'target':'IDH1 R132H','method':'PCR fluorescence probe'}),('Genetron TERT mutation detection kit','Fluorescence-PCR kit detecting TERT promoter C228T/C250T variants.',{'targets':['TERT C228T','TERT C250T'],'method':'PCR fluorescence probe'}),('Genetron PDGFRA D842V mutation detection kit','Fluorescence-PCR assay for PDGFRAD842V, listed for avapritinib companion testing; kit ownership does not imply drug ownership.',{'target':'PDGFRA D842V'}),('Genetron eight-gene mutation screening kit','NSCLC tissue DNA/RNA assay covering EGFR,KRAS,BRAF,HER2,PIK3CA,ALK,ROS1,MET using semiconductor sequencing.',{'gene_count':8,'China_registration_number':'20203400072','specimen':'FFPE tissue','method':'semiconductor sequencing'})]:ps.append(p(name,desc,a,'commercial',typ='product',sub='diagnostics',attributes=attrs,evidence=[a,b]))
