for name,desc in [('GENETRON 3D','Chip-based digital PCR instrument.'),('GENETRON S5','Semiconductor desktop high-throughput sequencing instrument.'),('GENETRON Chef','Automated library/template preparation and sequencing-chip loading instrument.'),('GENETRON S2000','cPAS/DNB-based medium/high-throughput sequencing instrument.')]:ps.append(p(name,desc,a,'commercial',roles=['commercial_partner'],typ='product',sub='research_tools',attributes={'manufacturer_identity':'Genetron branded offering; underlying hardware OEM rights not independently reconciled'}))
for name,desc,attrs in [('Onco PanScan tissue','831-gene tissue panel for pan-solid-tumor molecular analysis.',{'gene_count':831,'specimen':'tissue'}),('Onco PanScan blood','831-gene liquid-biopsy panel for pan-solid-tumor molecular analysis.',{'gene_count':831,'specimen':'blood'}),('Onco PanScan sarcoma','Sarcoma assay combining831-gene DNA and395-gene RNA/fusion analysis.',{'DNA_gene_count':831,'RNA_gene_count':395,'indication_scope':'sarcoma'}),('Onco Basic Plus blood','Selected solid-tumor gene testing service from blood.',{'specimen':'blood'}),('Onco Focus tissue','Medium-sized solid-tumor sequencing panel for molecular research and drug-target analysis.',{'specimen':'tissue'}),('Onco Sonar','Liquid-biopsy tumor-testing service listed for blood and pleural-fluid samples; detailed panel/version mapping not established.',{'listed_specimens':['blood','pleural fluid'],'identity_scope':'named assay family'}),('GENETRON MRD','Solid-tumor minimal-residual-disease testing service, distinct from B-cell SeqMRD.',{'disease_scope':'solid tumors'}),('HCCscreen','Liver-cancer early-detection biomarker testing offering, based on Mutation Capsule; current catalogue describes translational research support.',{'regulatory_note':'FDA Breakthrough Device designation is not marketing approval','current_catalogue_use':'research/translational-medicine support'}),('Genetron PD-L1 immunohistochemistry service','Laboratory PD-L1 immunohistochemical testing service, without attributing ownership of third-party antibody clones.',{'service_scope':'laboratory assay; exact antibody clone not established'}),('Genetron whole-exome tissue sequencing','21,000-gene whole-exome sequencing research/testing service; cancer report contexts not separate product identities.',{'gene_count':21000,'specimen':'tissue'})]:ps.append(p(name,desc,a,'commercial',roles=['commercial_partner'],typ='product',sub='diagnostics',attributes={**attrs,'clinical_approval_not_inferred':True},evidence=[a,b]))
for name,desc in [('Genetron One-Step Seq Method','Proprietary one-step library-construction/sequencing workflow technology.'),('Mutation Capsule','Genetron molecular biomarker-detection technology supporting HCCscreen.')]:ps.append(p(name,desc,a,'commercial',typ='technology',sub='research_tools',evidence=[a,b]))
cs=[company('Genetron Holdings Ltd',ps,[a,b,c],'22 reviewed kit/instrument/assay/platform identities. Tissue versus blood PanScan and sarcoma DNA/RNA panel separated; cancer indications and repeated website listings do not duplicate WES/PDL1/SeqMRD. HCCscreen Breakthrough designation not FDA approval; SARSCoV2 EUA not FDA clearance and current supply unknown. Detailed current device registrations, full Chinese catalogue variants, assay versions, reagent/consumable SKUs, inherited-risk panels and OEM licensing histories require further research.')]
